// Marfim gateway protocol v1 — Dart contract tests (W2.2).
//
// These tests pin the client-side contract from the SAME canonical
// fixtures the Rust gate G11 enforces: `fixtures/protocol/*.json`,
// regenerated byte-identically from `marfim_gateway::protocol`. When a
// fixture drifts, both the Rust gate and these tests fail.
//
// Run: cd contracts/dart && dart pub get && dart test

import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

Map<String, dynamic> loadFixture(String name) {
  final f = File('../../fixtures/protocol/$name');
  if (!f.existsSync()) {
    fail('missing fixture $name — run `dart test` from contracts/dart');
  }
  return jsonDecode(f.readAsStringSync()) as Map<String, dynamic>;
}

/// One parsed SSE frame: `id: <seq>\ndata: <json>\n\n`. Comment lines
/// (pings) start with ':' and never produce frames.
class Frame {
  Frame(this.id, this.data);
  final int? id;
  final String data;
  Map<String, dynamic> get json => jsonDecode(data) as Map<String, dynamic>;
}

/// Minimal SSE parser per the Marfim envelope. Frames are separated by
/// blank lines; `id:` and `data:` fields are single-line; comments are
/// skipped; frames without data are dropped.
List<Frame> parseSse(String raw) {
  final frames = <Frame>[];
  for (final block in raw.split('\n\n')) {
    if (block.trim().isEmpty) continue;
    int? id;
    final data = <String>[];
    for (final line in block.split('\n')) {
      if (line.startsWith(':')) continue;
      if (line.startsWith('id:')) {
        id = int.tryParse(line.substring(3).trim());
      } else if (line.startsWith('data:')) {
        data.add(line.substring(5).trim());
      }
    }
    if (data.isNotEmpty) frames.add(Frame(id, data.join('\n')));
  }
  return frames;
}

/// Last-Event-ID resume semantics: keep exactly the frames with
/// seq > last (the server replays the same window from its ring).
List<Frame> resumeAfter(List<Frame> frames, int last) =>
    frames.where((f) => f.id != null && f.id! > last).toList();

void main() {
  test('all four fixture files exist and parse', () {
    for (final name in ['frames.json', 'events.json', 'routes.json', 'errors.json']) {
      expect(loadFixture(name), isA<Map<String, dynamic>>(), reason: name);
    }
  });

  test('protocol version is pinned to "1"', () {
    expect(loadFixture('routes.json')['protocol'], '1');
    expect(loadFixture('events.json')['protocol'], '1');
  });

  test('ring data frame: id + data envelope, valid JSON event', () {
    final frames = loadFixture('frames.json') as Map<String, dynamic>;
    final raw = frames['ring_data_frame']! as String;
    final parsed = parseSse(raw);
    expect(parsed, hasLength(1));
    expect(parsed.single.id, 7);
    expect(parsed.single.json['event'], isNotEmpty);
    expect(parsed.single.json['event'], 'assistant_message');
  });

  test('ping comments carry no id and produce no frames', () {
    final frames = loadFixture('frames.json') as Map<String, dynamic>;
    expect(frames['ping'], ': ping\n\n');
    expect(parseSse(frames['ping']! as String), isEmpty);
  });

  test('ring terminal and lag markers are id-less data frames', () {
    final frames = loadFixture('frames.json') as Map<String, dynamic>;
    final terminal = parseSse(frames['ring_terminal_frame']! as String).single;
    expect(terminal.id, isNull);
    expect(terminal.json['event'], 'stream_deadline');
    final lag = parseSse(frames['ring_lag_marker']! as String).single;
    expect(lag.id, isNull);
    expect(lag.json['event'], 'lagged');
  });

  test('Last-Event-ID resume replays exactly the missed seqs', () {
    final frames = loadFixture('frames.json') as Map<String, dynamic>;
    final replay = parseSse(frames['ring_resume_replay']! as String);
    expect(replay.map((f) => f.id).toList(), [8, 9]);
    // client at seq 7: both missed frames replay
    expect(resumeAfter(replay, 7).map((f) => f.id).toList(), [8, 9]);
    // client at seq 8: only 9
    expect(resumeAfter(replay, 8).map((f) => f.id).toList(), [9]);
    // client at seq 9: nothing, no duplicates ever
    expect(resumeAfter(replay, 9), isEmpty);
  });

  test('prompt terminal frame carries a per-stream id', () {
    final frames = loadFixture('frames.json') as Map<String, dynamic>;
    final terminal = parseSse(frames['prompt_terminal_frame']! as String).single;
    expect(terminal.id, 2);
    expect(terminal.json['event'], 'turn_end');
    expect(terminal.json['stop_reason'], isA<String>());
  });

  test('events.json covers every bus event kind with an event field', () {
    final events = loadFixture('events.json')['events']! as Map<String, dynamic>;
    // 18 kinds in marfim-core Event; the fixture must cover all of them.
    expect(events, hasLength(18));
    for (final entry in events.entries) {
      final line = jsonDecode(entry.value as String) as Map<String, dynamic>;
      expect(line['event'], entry.key,
          reason: 'event kind must match its key: ${entry.key}');
    }
  });

  test('routes.json pins method, path and status for every route', () {
    final routes = loadFixture('routes.json')['routes']! as Map<String, dynamic>;
    expect(routes.keys, containsAll([
      'healthz', 'list_sessions', 'create_session', 'get_session',
      'close_session', 'prompt', 'steer', 'cancel', 'undo', 'rewind',
      'fork', 'session_events', 'events', 'approvals', 'resolve_approval',
      'config', 'fs_read', 'fs_list', 'fs_write', 'git_status', 'git_diff',
      'git_log', 'mcp',
    ]));
    for (final entry in routes.entries) {
      final r = entry.value as Map<String, dynamic>;
      expect(r['method'], isA<String>(), reason: entry.key);
      expect(r['path'], startsWith('/'), reason: entry.key);
      expect(r['status'], isA<int>(), reason: entry.key);
    }
  });

  test('fs routes answer in the tool envelope, not bare text', () {
    final routes = loadFixture('routes.json')['routes']! as Map<String, dynamic>;
    for (final name in ['fs_read', 'fs_list', 'fs_write']) {
      final resp = routes[name]['response'] as Map<String, dynamic>;
      expect(resp['tool'], isA<String>(), reason: name);
      expect(resp['output'], isA<String>(), reason: name);
    }
  });

  test('error bodies are exact strings with documented statuses', () {
    final errors = loadFixture('errors.json') as Map<String, dynamic>;
    final expected = {
      'unauthorized': 401,
      'host_not_allowed': 403,
      'origin_not_allowed': 403,
      'body_too_large': 413,
      'no_such_session': 404,
      'no_such_approval': 404,
      'not_found': 404,
      'nothing_to_undo': 409,
      'route_not_wired': 501,
    };
    expect(errors.keys, containsAll(expected.keys));
    for (final entry in expected.entries) {
      final e = errors[entry.key] as Map<String, dynamic>;
      expect(e['status'], entry.value, reason: entry.key);
      expect((e['body'] as Map<String, dynamic>)['error'], isNotEmpty,
          reason: entry.key);
    }
  });

  test('config view structurally excludes credential material', () {
    final config = loadFixture('routes.json')['routes']['config']['response']
        as Map<String, dynamic>;
    final blob = jsonEncode(config).toLowerCase();
    // "token" alone would false-positive on the legitimate
    // compact_threshold_tokens/bash_default_timeout_ms fields.
    for (final forbidden in ['api_key', 'apikey', 'authorization', 'secret_key', 'bearer']) {
      expect(blob.contains(forbidden), isFalse,
          reason: 'config view must never carry "$forbidden"');
    }
    expect(config['secrets'], 'redacted');
  });
}
